    def _dynamic_fill_hazard_feature_ready_ts_ns(
        *,
        exchange_ts_ns: int,
        provider_receive_ts_ns: int,
        event_type: str,
        source_ordinal: int,
    ) -> int:
        exchange_ns = int(exchange_ts_ns)
        if dynamic_fill_hazard_visibility_clock_mode == "legacy_mixed":
            return max(exchange_ns, int(provider_receive_ts_ns or 0))
        if (
            dynamic_fill_hazard_visibility_clock_mode
            == "provider_receive_sensitivity"
        ):
            if str(event_type) == "book":
                receive_ns = int(provider_receive_ts_ns or 0)
                return (
                    max(exchange_ns, receive_ns if receive_ns > 0 else exchange_ns)
                    + dynamic_fill_hazard_provider_feature_latency_ns
                )
            return exchange_ns + dynamic_fill_hazard_provider_trade_delay_ns
        if dynamic_fill_hazard_visibility_profile is None:
            raise RuntimeError("q90 AWS visibility profile is not initialized")
        source_stratified = (
            dynamic_fill_hazard_profile_mode == "profile_source_stratified"
        )
        event_salt = (
            0
            if source_stratified
            else (0xB00C if str(event_type) == "book" else 0x7ADE)
        )
        seed_clock = (
            exchange_ns
            // (
                dynamic_fill_hazard_visibility_profile.source_stratified_bucket_ms
                * 1_000_000
            )
            if source_stratified
            else exchange_ns
        )
        keyed_seed = _splitmix64(
            int(dynamic_fill_hazard_visibility_seed)
            ^ int(seed_clock)
            ^ (0 if source_stratified else (int(source_ordinal) << 1))
            ^ event_salt
        )
        delay_ms = dynamic_fill_hazard_visibility_profile.delay_ms(
            {
                "market_id": (
                    dynamic_fill_hazard_profile_market_id
                    if str(event_type) == "book"
                    else dynamic_fill_hazard_profile_trade_market_id
                ),
                "event_type": str(event_type),
                "transport": dynamic_fill_hazard_profile_transport,
            },
            mode=dynamic_fill_hazard_profile_mode,
            rng=random.Random(int(keyed_seed)),
        )
        return exchange_ns + int(round(float(delay_ms) * 1_000_000.0))

    def _dynamic_fill_hazard_policy_source_ts_ns(
        *,
        exchange_ts_ns: int,
        provider_receive_ts_ns: int,
    ) -> int:
        if dynamic_fill_hazard_visibility_clock_mode == "aws_profile":
            return int(exchange_ts_ns)
        receive_ns = int(provider_receive_ts_ns or 0)
        return receive_ns if receive_ns > 0 else int(exchange_ts_ns)

