    def _append_dynamic_fill_hazard_lifecycle_journal(
        order: Mapping[str, Any],
        source_event_type: str,
    ) -> None:
        hazard_id = str(order.get("trace_id", ""))
        lifecycle = dynamic_fill_hazard_lifecycles.get(hazard_id)
        if lifecycle is None:
            return
        dynamic_fill_hazard_lifecycle_journal.append(
            order_lifecycle_journal_payload(
                lifecycle=lifecycle,
                runtime_source="replay",
                source_event_type=str(source_event_type),
                client_order_id=hazard_id,
                exchange_order_id=int(order.get("trace_id", 0) or 0),
                symbol=str(params.get("symbol", "BTCUSDC") or "BTCUSDC"),
                side=str(order.get("side", "")),
                order_state=str(order.get("state", "")),
            )
        )

    def _dynamic_fill_hazard_cpp_mismatch(
        stage: str,
        details: Mapping[str, Any],
    ) -> None:
        nonlocal dynamic_fill_hazard_cpp_mismatch_count
        dynamic_fill_hazard_cpp_mismatch_count += 1
        normalized_stage = str(stage)
        dynamic_fill_hazard_cpp_mismatch_by_stage[normalized_stage] = int(
            dynamic_fill_hazard_cpp_mismatch_by_stage.get(normalized_stage, 0)
            + 1
        )
        payload = {
            "stage": normalized_stage,
            **{str(key): value for key, value in details.items()},
        }
        if (
            len(dynamic_fill_hazard_cpp_mismatch_trace)
            < dynamic_fill_hazard_cpp_mismatch_trace_max
        ):
            dynamic_fill_hazard_cpp_mismatch_trace.append(payload)
        if dynamic_fill_hazard_cpp_parity_strict:
            raise RuntimeError(
                "dynamic fill-hazard Python/C++ parity mismatch: "
                + json.dumps(payload, sort_keys=True, default=str)
            )

    def _dynamic_fill_hazard_cpp_check(
        condition: bool,
        stage: str,
        **details: Any,
    ) -> None:
        if not condition:
            _dynamic_fill_hazard_cpp_mismatch(stage, details)

    def _dynamic_fill_hazard_float_equal(
        left: Any,
        right: Any,
        *,
        rtol: float = 2e-11,
        atol: float = 1e-12,
    ) -> bool:
        try:
            lhs = float(left)
            rhs = float(right)
        except (TypeError, ValueError):
            return False
        if math.isnan(lhs) or math.isnan(rhs):
            return math.isnan(lhs) and math.isnan(rhs)
        return bool(math.isclose(lhs, rhs, rel_tol=rtol, abs_tol=atol))
