    def _record_order_lifecycle_submit(order: dict[str, Any], ts_ms: int) -> None:
        local_order_lifecycle.submit(order, int(ts_ms))
        if order_lifecycle_journal_v2_adapter is not None:
            order_lifecycle_journal_v2_adapter.submit(order, int(ts_ms))

    def _record_order_lifecycle_activate(
        order: dict[str, Any],
        *,
        visibility_ts_ms: int,
        exchange_ts_ms: int,
        mid: float,
    ) -> None:
        local_order_lifecycle.activate(order, int(exchange_ts_ms), mid=float(mid))
        if order_lifecycle_journal_v2_adapter is not None:
            order_lifecycle_journal_v2_adapter.activate(
                order,
                visibility_ts_ms=int(visibility_ts_ms),
                exchange_ts_ms=int(exchange_ts_ms),
            )

    def _record_order_lifecycle_reject(
        order: dict[str, Any],
        *,
        visibility_ts_ms: int,
        exchange_ts_ms: int,
        reason: str,
    ) -> None:
        local_order_lifecycle.reject(order, int(exchange_ts_ms), reason=str(reason))
        if order_lifecycle_journal_v2_adapter is not None:
            order_lifecycle_journal_v2_adapter.reject(
                order,
                visibility_ts_ms=int(visibility_ts_ms),
                exchange_ts_ms=int(exchange_ts_ms),
            )

    def _record_order_lifecycle_cancel_request(
        order: dict[str, Any],
        ts_ms: int,
        *,
        reason: str,
    ) -> None:
        local_order_lifecycle.request_cancel(order, int(ts_ms), reason=str(reason))
        if order_lifecycle_journal_v2_adapter is not None:
            order_lifecycle_journal_v2_adapter.request_cancel(order, int(ts_ms))

    def _record_order_lifecycle_cancel_ack(
        order: dict[str, Any],
        *,
        visibility_ts_ms: int,
        exchange_ts_ms: int,
        reason: str,
    ) -> None:
        local_order_lifecycle.cancel_ack(
            order,
            int(visibility_ts_ms),
            reason=str(reason),
        )
        if order_lifecycle_journal_v2_adapter is None:
            return
        if str(reason) in {"expired", "ioc_expired", "ioc_no_top_liquidity"}:
            order_lifecycle_journal_v2_adapter.expire(
                order,
                visibility_ts_ms=int(visibility_ts_ms),
                exchange_ts_ms=int(exchange_ts_ms),
            )
        else:
            order_lifecycle_journal_v2_adapter.cancel_ack(
                order,
                visibility_ts_ms=int(visibility_ts_ms),
                exchange_ts_ms=int(exchange_ts_ms),
            )

    def _record_order_lifecycle_fill(
        order: dict[str, Any],
        visibility_ts_ms: int,
        *,
        exchange_ts_ms: Optional[int] = None,
        fill_qty: float,
        remaining_before: float,
        remaining_after: float,
        fill_price: float,
        inventory_before: float,
        inventory_after: float,
        campaign_id: int,
        physical_fill_identity: str,
        economic_legs: tuple[dict[str, Any], ...],
    ) -> None:
        local_order_lifecycle.fill(
            order,
            int(visibility_ts_ms),
            fill_qty=float(fill_qty),
            remaining_before=float(remaining_before),
            remaining_after=float(remaining_after),
            fill_price=float(fill_price),
            inventory_before=float(inventory_before),
            inventory_after=float(inventory_after),
            campaign_id=int(campaign_id),
            physical_fill_identity=str(physical_fill_identity),
            economic_legs=economic_legs,
        )
        if order_lifecycle_journal_v2_adapter is not None:
            journal_full_fill = float(remaining_after) <= 1e-12
            order_lifecycle_journal_v2_adapter.fill(
                order,
                remaining_after=(
                    0.0 if journal_full_fill else float(remaining_after)
                ),
                visibility_ts_ms=int(visibility_ts_ms),
                exchange_ts_ms=int(
                    visibility_ts_ms
                    if exchange_ts_ms is None
                    else exchange_ts_ms
                ),
                full_fill=journal_full_fill,
            )

    def _campaign_legs_for_order_fill(
        order: Mapping[str, Any],
        *,
        ts_ms: int,
        side: str,
        inventory_before: float,
        inventory_after: float,
        fill_qty: float,
        fill_price: float,
        fee_rate: float,
        remaining_before: float,
        remaining_after: float,
    ) -> tuple[str, tuple[dict[str, Any], ...]]:
        trace_id = int(order.get("trace_id", -1) or -1)
        physical_identity = (
            f"replay_order_fill:{trace_id}:{int(ts_ms)}:"
            f"{float(remaining_before):.12g}->{float(remaining_after):.12g}"
        )
        opening_campaign_id = int(campaign_count) + int(
            (
                abs(float(inventory_before)) <= 1e-10
                and abs(float(inventory_after)) > 1e-10
            )
            or float(inventory_before) * float(inventory_after) < -1e-20
        )
        legs = campaign_fill_economic_legs(
            physical_fill_identity=physical_identity,
            side=side,
            inventory_before=inventory_before,
            inventory_after=inventory_after,
            fill_quantity=fill_qty,
            fill_price=fill_price,
            fee_rate=fee_rate,
            closing_campaign_id=int(campaign_count),
            opening_campaign_id=opening_campaign_id,
        )
        return physical_identity, legs

