    queue_value_runtime_event_source: dict[str, str] = {}
    queue_value_input_scope = ""

    def _queue_runtime_event_source(
        artifact: QueueReactiveHawkesArtifact,
    ) -> str:
        event_columns = dict(artifact.event_columns)
        if event_columns == NATIVE_EXCHANGE_EVENT_COLUMNS:
            if exchange_book_scheduler is None:
                raise ValueError(
                    "native queue-value artifact requires the "
                    "strategy-independent exchange-book scheduler"
                )
            return "native_exchange_exact_level"
        if event_columns == EVENT_COLUMNS:
            return "policy_visible_top_book"
        raise ValueError(
            "queue-value artifact uses an unsupported event-source mapping: "
            f"{event_columns}"
        )

    if queue_value_keep_cancel_enabled:
        raw_competing_bundle_path = str(
            params.get("queue_value_competing_risk_bundle_path", "") or ""
        ).strip()
        raw_bundle_path = str(
            params.get("queue_value_model_bundle_path", "") or ""
        ).strip()
        raw_queue_path = str(
            params.get("queue_value_hawkes_artifact_path", "") or ""
        ).strip()
        raw_microprice_path = str(
            params.get("queue_value_microprice_artifact_path", "") or ""
        ).strip()
        if raw_competing_bundle_path and (
            raw_bundle_path or raw_queue_path or raw_microprice_path
        ):
            raise ValueError(
                "the competing-risk queue-value bundle cannot be combined "
                "with legacy queue-value artifacts"
            )
        if (
            queue_value_action_family == "queue_value_net_keep_cancel"
            and not raw_competing_bundle_path
        ):
            raise ValueError(
                "queue_value_net_keep_cancel requires a frozen "
                "queue_value_competing_risk_bundle_path"
            )
