    args = ap.parse_args()
    if args.day:
        if args.start_time or args.end_time:
            raise SystemExit("--day cannot be combined with --start-time/--end-time")
        day_ts = pd.Timestamp(args.day, tz="UTC")
        args.start_time = day_ts.strftime("%Y-%m-%d 00:00")
        args.end_time = (day_ts + pd.Timedelta(days=1)).strftime("%Y-%m-%d 00:00")
    elif not args.start_time and not args.end_time:
        raise SystemExit("Provide --day YYYY-MM-DD or an explicit --start-time/--end-time window")
    VERBOSE = bool(args.verbose)
    if (args.bbo_dir is None) != (args.l2_dir is None):
        raise SystemExit("--bbo-dir and --l2-dir must be supplied together")
    if args.bbo_dir is not None and args.l2_dir is not None:
        BBO_DIR = args.bbo_dir.expanduser().resolve()
        L2_DIR = args.l2_dir.expanduser().resolve()
        if not BBO_DIR.is_dir():
            raise SystemExit(f"Historical BBO directory does not exist: {BBO_DIR}")
        if not L2_DIR.is_dir():
            raise SystemExit(f"Historical L2 directory does not exist: {L2_DIR}")

    # ── Load base params from config.yaml ──
    print("Loading config.yaml as base params …")
    base = load_tick_base_params(
        symbol=args.symbol,
        config_path=args.config,
        configure_symbol=configure_symbol,
        require_historical_bbo=False,
        queue_base=args.queue_base,
        queue_decay=args.queue_decay,
        queue_ahead_mode=args.queue_ahead_mode,
        queue_price_tolerance=args.queue_price_tolerance,
        min_historical_book_coverage=args.min_historical_book_coverage,
        maker_fill_prob=args.maker_fill_prob,
    )
    base["current_e3_mechanics_default"] = False
    base["baseline_selection"] = (
        "explicit_config_arm"
        if args.config is not None
        else str(base.get("_config_source", "public_template"))
    )
    run_ml = bool(base.get("ml_enabled", False)) if args.ml is None else bool(args.ml)
    base["ml_enabled"] = run_ml

    import platform
    print(f"\n{'='*60}")
    print(
        f"  {SYMBOL} Tick-Level Backtest "
        f"({args.execution_trade_source}, live-aligned)"
    )
